package com.tutorhub.notification.controller;import com.tutorhub.common.security.CurrentUser;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController {private final JdbcTemplate j;private final CurrentUser c;public NotificationController(JdbcTemplate j,CurrentUser c){this.j=j;this.c=c;}@GetMapping List<Map<String,Object>> list(){return j.queryForList("select id,type,title,body,data,read_at,created_at from notifications where user_id=? order by created_at desc",c.require().id());}@GetMapping("/unread-count") Map<String,Integer> count(){return Map.of("count",j.queryForObject("select count(*) from notifications where user_id=? and read_at is null",Integer.class,c.require().id()));}@PostMapping("/{id}/read") void read(@PathVariable Long id){j.update("update notifications set read_at=now() where id=? and user_id=?",id,c.require().id());}@PostMapping("/read-all")void all(){j.update("update notifications set read_at=now() where user_id=? and read_at is null",c.require().id());}}
